/* Cross-check: load network.quant, build positions from EPDs, and dump
 * amy's own accumulators and NNUE score so the Python implementation
 * (amy-training-nnue/quantize.py QuantizedNet) can be verified bit-exact.
 * Also dumps the feature index sets (piece, pawn, attack) generated by
 * the engine itself, for the same purpose.
 *
 * Also dumps the intermediate int32 layer values ("I" lines) of a
 * copy of the integer pipeline to debug rounding/overflow issues.
 */
#include <assert.h>
#include <stdio.h>
#include <string.h>

#include "attack_map.h"
#include "dbase.h"
#include "hashtable.h"
#include "init.h"
#include "movedata.h"
#include "neural_net.h"
#include "utils.h"

extern int8_t input_layer_weights_q[];
extern int16_t hidden_layer_1_weights_q[NN_PHASE_COUNT][HIDDEN_1_SIZE]
                                       [2 * ACCUMULATOR_SIZE];
extern int32_t hidden_layer_1_bias_q[NN_PHASE_COUNT][HIDDEN_1_SIZE];
extern int16_t hidden_layer_2_weights_q[NN_PHASE_COUNT][HIDDEN_2_SIZE]
                                       [HIDDEN_1_SIZE];
extern int32_t hidden_layer_2_bias_q[NN_PHASE_COUNT][HIDDEN_2_SIZE];
extern int32_t output_layer_weights_q[NN_PHASE_COUNT][HIDDEN_2_SIZE];
extern int32_t output_layer_bias_q[NN_PHASE_COUNT][1];

#define SCALE 8192
#define SCALE_HALF 4095
#define SCALE_INPUT 64
#define SCALE_INPUT_HALF (SCALE_INPUT / 2 - 1)
#define SCALE_OUTPUT 10000

/* Must mirror neural_net.c: hidden-1 fixed-point scale. */
#define SCALE_H1 (SCALE_INPUT * SCALE)
#define SCALE_H1_HALF (SCALE_H1 / 2 - 1)

/* A copy of the integer pipeline of nn_evaluate_position() that
 * prints the intermediate values. */
static int instrumented_eval(struct Position *p) {
    int phase = nn_phase_index(p);
    int32_t h1q[HIDDEN_1_SIZE];
    for (int i = 0; i < HIDDEN_1_SIZE; i++) {
        h1q[i] = hidden_layer_1_bias_q[phase][i];
    }
    int16_t acc[2 * ACCUMULATOR_SIZE];
    if (p->turn == White) {
        memcpy(acc, p->accumulator_w_q, ACCUMULATOR_SIZE * sizeof(int16_t));
        memcpy(acc + ACCUMULATOR_SIZE, p->accumulator_b_q,
               ACCUMULATOR_SIZE * sizeof(int16_t));
    } else {
        memcpy(acc, p->accumulator_b_q, ACCUMULATOR_SIZE * sizeof(int16_t));
        memcpy(acc + ACCUMULATOR_SIZE, p->accumulator_w_q,
               ACCUMULATOR_SIZE * sizeof(int16_t));
    }
    for (int i = 0; i < 2 * ACCUMULATOR_SIZE; i++) {
        if (acc[i] < 0)
            acc[i] = 0;
        if (acc[i] > SCALE_INPUT)
            acc[i] = SCALE_INPUT;
    }
    for (int i = 0; i < HIDDEN_1_SIZE; i++) {
        for (int j = 0; j < 2 * ACCUMULATOR_SIZE; j++) {
            h1q[i] += acc[j] * hidden_layer_1_weights_q[phase][i][j];
        }
        printf("I H1Q %d %d\n", i, (int)h1q[i]);
    }
    int16_t h1[HIDDEN_1_SIZE];
    for (int i = 0; i < HIDDEN_1_SIZE; i++) {
        if (h1q[i] <= 0)
            h1[i] = 0;
        else if (h1q[i] > SCALE_H1)
            h1[i] = SCALE_INPUT;
        else
            h1[i] = (h1q[i] + SCALE_HALF) / SCALE;
        printf("I H1 %d %d\n", i, (int)h1[i]);
    }
    int32_t h2q[HIDDEN_2_SIZE];
    memcpy(h2q, hidden_layer_2_bias_q[phase], HIDDEN_2_SIZE * sizeof(int32_t));
    for (int i = 0; i < HIDDEN_2_SIZE; i++) {
        for (int j = 0; j < HIDDEN_1_SIZE; j++) {
            h2q[i] += h1[j] * hidden_layer_2_weights_q[phase][i][j];
        }
        printf("I H2Q %d %d\n", i, (int)h2q[i]);
    }
    int16_t h2[HIDDEN_2_SIZE];
    for (int i = 0; i < HIDDEN_2_SIZE; i++) {
        if (h2q[i] <= 0)
            h2[i] = 0;
        else if (h2q[i] >= SCALE_INPUT * SCALE)
            h2[i] = SCALE;
        else
            h2[i] = (h2q[i] + SCALE_INPUT_HALF) / SCALE_INPUT;
        printf("I H2 %d %d\n", i, (int)h2[i]);
    }
    int32_t out_q = output_layer_bias_q[phase][0];
    for (int j = 0; j < HIDDEN_2_SIZE; j++) {
        out_q += h2[j] * output_layer_weights_q[phase][j];
    }
    printf("I OUTQ %d\n", (int)out_q);
    int score = ((out_q + SCALE_HALF) / SCALE) * SCALE_OUTPUT;
    score = (score + SCALE_HALF) / SCALE;
    return score;
}

/* Dump one feature index set: <tag> <W|B> <count> <indices...>. */
static void dump_set(const char *tag, const char *side, const int *v, int n) {
    printf("%s %s %d", tag, side, n);
    for (int k = 0; k < n; k++)
        printf(" %d", v[k]);
    printf("\n");
}

int main(void) {
    utils_open_log_file("Amy.log");
    movedata_init();
    init_all();
    ht_init();
    ht_allocate();
    nn_read_weights();

    const char *epds[] = {
        "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq -",
        "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR b KQkq -",
        "r1bqkb1r/pppp1ppp/2n2n2/1B2p3/4P3/5N2/PPPP1PPP/RNBQK2R w KQkq -",
        "3r1k2/p3qppP/8/3p4/3r4/5QP1/P4PB1/4R1K1 w - -",
        "rnbqkbnr/1pp1pppp/p7/3pP3/8/8/PPPP1PPP/RNBQKBNR w KQkq d6",
        /* Both kings on the left half (non-mirrored frame): the
         * horizontal mirror of the previous EPD. */
        "2k1r3/Pppq3p/8/4p3/4r3/1PQ5/1BP4P/1K1R4 w - -",
        /* Phase 0 (1 non-pawn piece). */
        "r7/8/8/8/8/8/4K2k/8 w - -",
        /* Boundary: 2 non-pawn pieces, top of phase 0 (nn_phase_masks
         * activates phases 0 and 1). */
        "3r1r2/8/8/8/8/8/4K2k/8 w - -",
        /* Phase 1 (3 non-pawn pieces). */
        "2R1r1r1/8/8/8/8/8/4K2k/8 w - -",
    };

    const size_t n_epds = sizeof(epds) / sizeof(epds[0]);

    for (int i = 0; i < (int)n_epds; i++) {
        struct Position *p = dbase_create_position_from_epd((char *)epds[i]);
        nn_init_accumulator(p);
        nn_validate_weights(p);
        printf("POS %d turn %d\n", i, p->turn);
        printf("PHASE %d\n", nn_phase_index(p));
        int masks[NN_PHASE_COUNT];
        nn_phase_masks(p, masks);
        printf("PMASKS");
        for (int m = 0; m < NN_PHASE_COUNT; m++) {
            printf(" %d", masks[m]);
        }
        printf("\n");
        for (int k = 0; k < ACCUMULATOR_SIZE; k++) {
            printf("%d", p->accumulator_w_q[k]);
            if (k < ACCUMULATOR_SIZE - 1)
                fputc(' ', stdout);
        }
        printf("\n");
        for (int k = 0; k < ACCUMULATOR_SIZE; k++) {
            printf("%d", p->accumulator_b_q[k]);
            if (k < ACCUMULATOR_SIZE - 1)
                fputc(' ', stdout);
        }
        printf("\n");
        printf("SCORE %d\n", nn_evaluate_position(p));
        printf("SCOREI %d\n", instrumented_eval(p));

        /* Feature index sets (the engine's own generation). */
        int feat_w[NN_MAX_PIECE_FEATURES], feat_b[NN_MAX_PIECE_FEATURES];
        int pfeat_w[NN_MAX_PAWN_FEATURES], pfeat_b[NN_MAX_PAWN_FEATURES];
        int afeat_w[NN_MAX_ATTACK_FEATURES], afeat_b[NN_MAX_ATTACK_FEATURES];
        int n;
        n = nn_compute_piece_indices(p, White, feat_w, NN_MAX_PIECE_FEATURES);
        assert(n >= 0);
        dump_set("FEAT", "W", feat_w, n);
        n = nn_compute_piece_indices(p, Black, feat_b, NN_MAX_PIECE_FEATURES);
        assert(n >= 0);
        dump_set("FEAT", "B", feat_b, n);
        n = nn_compute_pawn_indices(p, White, pfeat_w, NN_MAX_PAWN_FEATURES);
        assert(n >= 0);
        dump_set("PFEAT", "W", pfeat_w, n);
        n = nn_compute_pawn_indices(p, Black, pfeat_b, NN_MAX_PAWN_FEATURES);
        assert(n >= 0);
        dump_set("PFEAT", "B", pfeat_b, n);
        n = am_compute_attack_indices(p, White, afeat_w,
                                      NN_MAX_ATTACK_FEATURES);
        assert(n >= 0);
        dump_set("AFEAT", "W", afeat_w, n);
        n = am_compute_attack_indices(p, Black, afeat_b,
                                      NN_MAX_ATTACK_FEATURES);
        assert(n >= 0);
        dump_set("AFEAT", "B", afeat_b, n);
        dbase_free_position(p);
    }
    return 0;
}
